function demo(){bayEditIndex=null;$('bay-submit').textContent='Bay 추가';const make=(id,layer,x,y,w,h)=>({id,handle:id,type:'LWPOLYLINE',space:'model',layer,classification:guessCategory(layer),version:1,notes:'',data:{type:'LWPOLYLINE',handle:id,layer,flag:1,vertices:[{x,y},{x:x+w,y},{x:x+w,y:y+h},{x,y:y+h}]}});records=sample().map(o=>{const r=make(o.id,'PRODUCTION_BOX',o.x,o.y,o.w,o.h);r.data._locked=o.locked;return r;});records.push(make('AISLE-A','인동선',0,16,60,4),make('PIPE-A','배관',1,2,55,.3),make('DUCT-A','덕트',1,33,55,.8),make('RACK-A','전기 모듈랙',57,1,1,32));drawing={id:'demo',name:'FAB-01 / 통합 예시 Bay',revision:1,status:'ready',metadata:{layers:[],blocks:[],bays:[{name:'BAY-A',x:0,y:0,w:60,h:36}],groups:[],codeLinks:[],layerMap:{},units:6,unitsConfirmed:true,expectedBoxes:8,clearance:1}};saved=structuredClone(records);dirty.clear();metaDirty=false;selected=new Set([records[0].id]);hiddenLayers.clear();render();fit();refreshHistory();const f=$('bay-form');f.elements.x.value=0;f.elements.y.value=0;f.elements.w.value=60;f.elements.h.value=36;message('예시 모델을 열었습니다. 변경은 임시 검토용입니다.');}
async function refresh(){drawings=(await api('/drawings')).drawings;$('connection-state').textContent='서버 DB 연결됨';renderDB();}
async function loadDrawing(id){const result=await api(`/drawings/${id}`);const list=[];let offset=0;do{const data=await api(`/drawings/${id}/entities?offset=${offset}`);list.push(...data.entities);offset=data.next;}while(offset!==null);drawing=result.drawing;bayEditIndex=null;$('bay-submit').textContent='Bay 추가';records=list;saved=structuredClone(records);dirty.clear();metaDirty=false;selected=new Set(records[0]?[records[0].id]:[]);hiddenLayers.clear();page=0;render();fit();const b=drawingBounds(items),f=$('bay-form');f.elements.x.value=b.x;f.elements.y.value=b.y;f.elements.w.value=b.w;f.elements.h.value=b.h;await refreshHistory();message(`실제 DWG 객체 ${records.length}개를 불러왔습니다. 레이어·BOX 검수를 진행하세요.`);}
async function refreshHistory(){if(drawing.id==='demo'){$('edit-history').innerHTML='<p class="cad-note">예시는 서버 이력을 만들지 않습니다.</p>';return;}const data=await api(`/drawings/${drawing.id}/history`);$('edit-history').innerHTML=data.edits.length?data.edits.map(e=>`<details class="history-row"><summary><small>${escape(new Date(e.created_at).toLocaleString('ko-KR'))}</small>${escape(e.reason)}</summary><p>객체: ${escape(e.entity_id||'도면 기준')}</p><pre>${escape(e.before_data)}\n→\n${escape(e.after_data)}</pre></details>`).join(''):'<p class="cad-note">저장 후 편집한 이력이 없습니다.</p>';}
function startSave(){if(!dirty.size&&!metaDirty){message('저장할 변경이 없습니다.');return;}if(drawing.id==='demo'){message('예시 변경은 임시 검토용입니다. 실제 DWG를 업로드하면 서버 DB에 저장할 수 있습니다.');return;}$('save-summary').textContent=`${dirty.size}개 객체${metaDirty?'와 Bay·레이어 기준':''}의 변경을 R${drawing.revision+1}로 저장합니다.`;$('save-dialog').showModal();}
async function saveChanges(reason){const changes=records.filter(r=>dirty.has(r.id)).map(r=>({id:r.id,version:r.version,data:r.data,layer:r.layer,classification:r.classification,notes:r.notes||''}));const pending=[...changes];let first=true;do{const chunk=pending.splice(0,40);const result=await post(`/drawings/${drawing.id}/change`,{revision:drawing.revision,changes:chunk,metadata:first&&metaDirty?drawing.metadata:undefined,reason});drawing.revision=result.revision;for(const c of chunk){dirty.delete(c.id);const r=records.find(r=>r.id===c.id);r.version++;}if(first)metaDirty=false;first=false;}while(pending.length);$('save-dialog').close();await loadDrawing(drawing.id);await refresh();message('서버 DB에 저장했습니다. 변경된 개정의 검수를 다시 진행하세요.');}
function validateEdit(data,r){if(!data||data.type!==r.type||data.handle!==r.data.handle)throw new Error('객체 종류와 Handle은 원본대로 유지해야 합니다.');if(data._placement&&!['x','y'].every(k=>Number.isFinite(data._placement[k])))throw new Error('이동량 X·Y는 유효한 숫자여야 합니다.');if(JSON.stringify(data).length>180000)throw new Error('객체 JSON이 너무 큽니다.');}
