$('object-form').onsubmit=e=>{e.preventDefault();const r=selectedRecord();if(!r)return;const f=e.currentTarget,dx=Number(f.elements.dx.value),dy=Number(f.elements.dy.value);if(r.data._locked&&f.elements.locked.checked&&(dx!==(r.data._placement?.x||0)||dy!==(r.data._placement?.y||0))){message('위치 고정을 해제한 뒤 이동하세요.',true);return;}r.data={...r.data,_placement:{x:dx,y:dy},_locked:f.elements.locked.checked,_classificationOverride:true,layer:f.elements.layer.value};r.layer=f.elements.layer.value;r.classification=f.elements.classification.value;r.notes=f.elements.notes.value;const group=drawing.metadata.groups.find(g=>g.memberIds.includes(r.id)),code=f.elements.constructionCode.value.trim(),targets=group?group.memberIds:[r.id];for(const target of records.filter(x=>targets.includes(x.id)))target.data._constructionCode=code;mark(targets);render();message('객체 속성을 적용했습니다. 변경 저장을 눌러 DB에 반영하세요.');};
$('criteria-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;Object.assign(drawing.metadata,{units:Number(f.elements.units.value),unitsConfirmed:f.elements.unitsConfirmed.checked,expectedBoxes:Number(f.elements.expectedBoxes.value),clearance:Number(f.elements.clearance.value)});metaDirty=true;render();};
$('bay-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,b={name:f.elements.name.value};for(const k of ['x','y','w','h','serviceWidth'])b[k]=Number(f.elements[k].value);b.serviceSide=f.elements.serviceSide.value;if(b.serviceWidth>=(['top','bottom'].includes(b.serviceSide)?b.h:b.w)){message('인프라 구역 폭은 Bay보다 작아야 합니다.',true);return;}if(bayEditIndex===null)drawing.metadata.bays.push(b);else drawing.metadata.bays[bayEditIndex]=b;bayEditIndex=null;$('bay-submit').textContent='Bay 추가';metaDirty=true;render();message(`${b.name} 경계를 추가했습니다. 모든 위치·크기는 도면 단위입니다.`);};
$('group-box').onclick=()=>{if(selected.size<2){message('Shift+클릭으로 설비를 구성하는 여러 선을 먼저 선택하세요.');return;}if(drawing.metadata.groups.some(g=>g.memberIds.some(id=>selected.has(id)))){message('이미 다른 BOX에 묶인 객체가 포함되어 있습니다.',true);return;}const members=[...selected];if(members.some(id=>!items.find(i=>i.id===id)?.primitives.some(p=>p.kind==='path'))){message('문자는 BOX 외곽에 포함할 수 없습니다. 선 형상만 선택하세요.',true);return;}drawing.metadata.groups.push({id:crypto.randomUUID(),name:`BOX-${drawing.metadata.groups.length+1}`,memberIds:members});for(const r of records.filter(r=>selected.has(r.id))){r.classification='box';r.data._classificationOverride=true;}metaDirty=true;mark(members);render();message('선택 형상을 하나의 생산설비 BOX로 묶었습니다. 구성 형상은 함께 이동합니다.');};
$('ungroup-box').onclick=()=>{const before=drawing.metadata.groups.length;drawing.metadata.groups=drawing.metadata.groups.filter(g=>!g.memberIds.some(id=>selected.has(id)));if(drawing.metadata.groups.length===before){message('해제할 BOX 그룹을 선택하세요.');return;}metaDirty=true;render();message('BOX 그룹을 해제했습니다. 각 형상의 공종 분류를 다시 확인하세요.');};
$('clear-selection').onclick=()=>{selected.clear();renderProperties();draw();};$('inspect').onclick=()=>{render();message(`검수·배치 확인 ${inspectDrawing(records,drawing.metadata).issues.length}건. 아래 검수 목록을 확인하세요.`);};$('review').onclick=guarded(async()=>{await post(`/drawings/${drawing.id}/review`,{revision:drawing.revision});await loadDrawing(drawing.id);message('현재 개정의 레이어·BOX·Bay 검수를 완료했습니다. 실제 설계 승인은 별도입니다.');});$('discard').onclick=guarded(async()=>{if(drawing.id==='demo')demo();else await loadDrawing(drawing.id);});
$('auto-bay').onclick=guarded(()=>{const proposal=proposeBay(records,drawing.metadata);records=proposal.records;mark(proposal.moves.map(m=>m.id));render();message(`Bay 배치 제안 ${proposal.moves.length}개 이동 · 재검사 통과. 변경 저장 전에 도면에서 검토하세요.`);});
