$('db-edit-form').onsubmit=guarded(e=>{e.preventDefault();const r=selectedRecord();if(!r)throw new Error('객체를 선택하세요.');const data=JSON.parse($('entity-json').value);validateEdit(data,r);r.data=data;r.layer=String(data.layer||r.layer);r.notes=$('db-notes').value;mark([r.id]);render();message('JSON 편집을 적용했습니다. 서버 저장 후에도 원본 추출값은 보존됩니다.');});
$('show-original').onclick=guarded(async()=>{const r=selectedRecord();if(!r)return;const original=drawing.id==='demo'?saved.find(s=>s.id===r.id)?.data:(await api(`/drawings/${drawing.id}/source?entity=${encodeURIComponent(r.id)}`)).original;$('original-json').textContent=JSON.stringify(original,null,2);$('original-json').hidden=false;});
const world=e=>{const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('cad-plan').getScreenCTM().inverse());return {x:p.x,y:-p.y};};
$('cad-plan').onpointerdown=e=>{const g=e.target.closest('[data-record]'),p=world(e);if(!g){drag={pan:true,clientX:e.clientX,clientY:e.clientY,view:{...view}};$('cad-plan').setPointerCapture(e.pointerId);return;}const id=g.dataset.record;if(e.shiftKey){selected.has(id)?selected.delete(id):selected.add(id);renderProperties();draw();return;}const group=drawing.metadata.groups.find(g=>g.memberIds.includes(id));if(group)selected=new Set(group.memberIds);else if(!selected.has(id))selected=new Set([id]);for(const link of drawing.metadata.codeLinks||[])if(link.boxId===(group?.id||id))selected.add(link.entityId);renderProperties();draw();if(records.some(r=>selected.has(r.id)&&r.data._locked)){message('선택한 객체에 위치 고정이 포함되어 있습니다.');return;}drag={start:p,ids:[...selected],dx:0,dy:0};$('cad-plan').setPointerCapture(e.pointerId);};
$('cad-plan').onpointermove=e=>{if(!drag)return;if(drag.pan){const rect=$('cad-plan').getBoundingClientRect();view={...drag.view,x:drag.view.x-(e.clientX-drag.clientX)*drag.view.w/rect.width,y:drag.view.y-(e.clientY-drag.clientY)*drag.view.h/rect.height};$('cad-plan').setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);return;}const p=world(e);drag.dx=p.x-drag.start.x;drag.dy=p.y-drag.start.y;for(const g of $('cad-plan').querySelectorAll('[data-record]'))if(drag.ids.includes(g.dataset.record))g.setAttribute('transform',`translate(${drag.dx} ${drag.dy})`);};
$('cad-plan').onpointerup=()=>{if(!drag)return;if(!drag.pan&&Math.hypot(drag.dx,drag.dy)>1e-8){for(const r of records.filter(r=>drag.ids.includes(r.id))){r.data._placement={x:(r.data._placement?.x||0)+drag.dx,y:(r.data._placement?.y||0)+drag.dy};}mark(drag.ids);render();message('도면 위치를 이동했습니다. 변경 저장으로 서버 DB에 반영하세요.');}drag=null;};$('cad-plan').onpointercancel=()=>{drag=null;draw();};
$('cad-plan').addEventListener('wheel',e=>{e.preventDefault();const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('cad-plan').getScreenCTM().inverse()),factor=e.deltaY>0?1.15:1/1.15;view={x:p.x+(view.x-p.x)*factor,y:p.y+(view.y-p.y)*factor,w:view.w*factor,h:view.h*factor};draw();},{passive:false});
