$('repair-apply').onclick=guarded(()=>{if(!repairProposal||repairSnapshot!==repairFingerprint())throw new Error('도면이 바뀌었습니다. 수정 후보를 다시 분석하세요.');const proposal=repairProposal;repairProposal=null;records=proposal.records;drawing.metadata=proposal.metadata;mark(proposal.changedIds);metaDirty=true;$('repair-apply').disabled=true;render();message(`BOX 정리 ${proposal.changes.length}건 적용 · ${proposal.warnings.length}개 확인 항목. 변경 저장을 눌러 DB와 이력에 반영하세요.`);});
