if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'inspect_dwg_workspace',description:'현재 도면의 DB 상태, 레이어, BOX 검수와 Bay 정보를 읽습니다.',annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('빈 객체가 필요합니다.');const qc=inspectDrawing(records,drawing.metadata);return {drawing:{id:drawing.id,name:drawing.name,revision:drawing.revision},entities:records.length,boxes:qc.boxes,issues:qc.issues,bays:drawing.metadata.bays,unsavedEntities:dirty.size};}}]){try{document.modelContext.registerTool({...tool,inputSchema:{type:'object',properties:{},additionalProperties:false}},{signal:lifecycle.signal});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
